function GlassGloryHoleDamperMaker.init() GlassGloryHoleDamperMaker.ironStock=16; GlassGloryHoleDamperMaker.bronzeStock=12; GlassGloryHoleDamperMaker.woodStock=12; GlassGloryHoleDamperMaker.leatherStock=8; GlassGloryHoleDamperMaker.silverStock=8; GlassGloryHoleDamperMaker.goldStock=6; GlassGloryHoleDamperMaker.jewelStock=4; GlassGloryHoleDamperMaker.pearlStock=4; GlassGloryHoleDamperMaker.productStock={}; GlassGloryHoleDamperMaker.buildings={}; GlassGloryHoleDamperMaker.maker=nil; GlassGloryHoleDamperMaker.activeMaking={}; GlassGloryHoleDamperMaker.totalProducts=0; GlassGloryHoleDamperMaker.dayTimer=0; print("[GlassGloryHoleDamperMaker] Royal Glass Glory Hole Damper Maker System initialized (6 products, 4 buildings)") end
function GlassGloryHoleDamperMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GlassGloryHoleDamperMaker.maker={name=n or ("Zaklopnik "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopnik najet: %s (spretnost: %d)",GlassGloryHoleDamperMaker.maker.name,s),"success") end; return true end
function GlassGloryHoleDamperMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GlassGloryHoleDamperMaker.build(id) local ok,e=GlassGloryHoleDamperMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GlassGloryHoleDamperMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GlassGloryHoleDamperMaker.getQualityBonus() local b=0; for _,bd in ipairs(GlassGloryHoleDamperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GlassGloryHoleDamperMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GlassGloryHoleDamperMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GlassGloryHoleDamperMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GlassGloryHoleDamperMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GlassGloryHoleDamperMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GlassGloryHoleDamperMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GlassGloryHoleDamperMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GlassGloryHoleDamperMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GlassGloryHoleDamperMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GlassGloryHoleDamperMaker.buildings==0 then return false,"Potrebna zaklopna delavnica" end; if not GlassGloryHoleDamperMaker.maker then return false,"Potreben zaklopnik" end; return true end
function GlassGloryHoleDamperMaker.make(pt,qty) qty=qty or 1; local ok,e=GlassGloryHoleDamperMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GlassGloryHoleDamperMaker.ironStock=GlassGloryHoleDamperMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GlassGloryHoleDamperMaker.bronzeStock=GlassGloryHoleDamperMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GlassGloryHoleDamperMaker.woodStock=GlassGloryHoleDamperMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GlassGloryHoleDamperMaker.leatherStock=GlassGloryHoleDamperMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GlassGloryHoleDamperMaker.silverStock=GlassGloryHoleDamperMaker.silverStock-d.silverCost*qty end; if d.goldCost then GlassGloryHoleDamperMaker.goldStock=GlassGloryHoleDamperMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GlassGloryHoleDamperMaker.jewelStock=GlassGloryHoleDamperMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GlassGloryHoleDamperMaker.pearlStock=GlassGloryHoleDamperMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GlassGloryHoleDamperMaker.maker then t=math.max(1,t-math.floor(GlassGloryHoleDamperMaker.maker.skill/13)) end; table.insert(GlassGloryHoleDamperMaker.activeMaking,{id="glassgloryholedamper_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GlassGloryHoleDamperMaker.completeMaking(m) local q=1.0+(GlassGloryHoleDamperMaker.getQualityBonus()/100); if GlassGloryHoleDamperMaker.maker then q=q+(GlassGloryHoleDamperMaker.maker.skill/140) end; q=math.min(2.5,q); GlassGloryHoleDamperMaker.productStock[m.productType]=(GlassGloryHoleDamperMaker.productStock[m.productType] or 0)+m.quantity; GlassGloryHoleDamperMaker.totalProducts=GlassGloryHoleDamperMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GlassGloryHoleDamperMaker.maker then GlassGloryHoleDamperMaker.maker.itemsMade=GlassGloryHoleDamperMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GlassGloryHoleDamperMaker.maker.skill=math.min(100,GlassGloryHoleDamperMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zaklopnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"glassgloryholedamper.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GlassGloryHoleDamperMaker.update(dt) if not _G.state then return end; GlassGloryHoleDamperMaker.dayTimer=GlassGloryHoleDamperMaker.dayTimer+dt; if GlassGloryHoleDamperMaker.dayTimer>=30 then GlassGloryHoleDamperMaker.dayTimer=0; for i=#GlassGloryHoleDamperMaker.activeMaking,1,-1 do local m=GlassGloryHoleDamperMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GlassGloryHoleDamperMaker.completeMaking(m); table.remove(GlassGloryHoleDamperMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GlassGloryHoleDamperMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GlassGloryHoleDamperMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
